import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { SharedArray } from 'k6/data';

// ─── Manifest (generated by generate_seed_data_v2.py) ────
const MANIFEST_PATH = __ENV.MANIFEST_PATH || '/tmp/coredisc-seed-v2/manifest.json';
let manifest;
try {
    manifest = JSON.parse(open(MANIFEST_PATH));
} catch (e) {
    // Fallback: minimal manifest for when file isn't available
    manifest = {
        hot_post_ids: [],
        circle_pairs: [],
        block_pairs: [],
        tiers: {
            T1: { member_ids: Array.from({ length: 10 }, (_, i) => i + 1) },
            T2: { member_ids: Array.from({ length: 100 }, (_, i) => i + 11) },
            T3: { member_ids: Array.from({ length: 200 }, (_, i) => i + 511) },
            T4: { member_ids: Array.from({ length: 50 }, (_, i) => i + 5011) },
        },
    };
}

// ─── Custom Metrics ──────────────────────────────────────
const feedDuration = new Trend('feed_duration', true);
const feedCoreDuration = new Trend('feed_core_duration', true);
const postDetailDuration = new Trend('post_detail_duration', true);
const postCreateDuration = new Trend('post_create_duration', true);
const commentCreateDuration = new Trend('comment_create_duration', true);
const hotPostDuration = new Trend('hot_post_duration', true);
const likeDuration = new Trend('like_duration', true);
const profileDuration = new Trend('profile_duration', true);
const notificationDuration = new Trend('notification_duration', true);
const searchDuration = new Trend('search_duration', true);
const questionDuration = new Trend('question_duration', true);
const followDuration = new Trend('follow_duration', true);
const errorRate = new Rate('error_rate');
const requestCount = new Counter('total_requests');

// ─── Configuration ───────────────────────────────────────
const BASE_URL = __ENV.BASE_URL || 'http://localhost:8080';
const TEST_PASSWORD = 'testpass123a';

// Tier-based user pool sizes
const T1_USERS = 5;
const T2_USERS = 100;
const T3_USERS = 200;
const T4_USERS = 50;

// ─── Scenarios ───────────────────────────────────────────
export const options = {
    scenarios: {
        read_heavy: {
            executor: 'ramping-vus',
            startVUs: 0,
            stages: [
                { duration: '30s', target: 20 },    // warm-up
                { duration: '1m', target: 80 },      // ramp
                { duration: '2m', target: 150 },     // peak
                { duration: '5m', target: 150 },     // sustain
                { duration: '1m30s', target: 0 },    // cool-down
            ],
            gracefulRampDown: '10s',
            exec: 'readScenario',
        },
        write_operations: {
            executor: 'ramping-vus',
            startVUs: 0,
            stages: [
                { duration: '30s', target: 5 },
                { duration: '1m', target: 20 },
                { duration: '2m', target: 30 },
                { duration: '5m', target: 30 },
                { duration: '1m30s', target: 0 },
            ],
            gracefulRampDown: '10s',
            exec: 'writeScenario',
        },
    },
    thresholds: {
        feed_duration: ['p(95)<500'],
        feed_core_duration: ['p(95)<500'],
        post_detail_duration: ['p(95)<500'],
        post_create_duration: ['p(95)<1000'],
        comment_create_duration: ['p(95)<1000'],
        error_rate: ['rate<0.05'],
        http_req_duration: ['p(95)<2000'],
    },
};

// ─── Setup: Login tier-based user pool ───────────────────
export function setup() {
    console.log('Logging in tier-based user pool...');

    const userPool = [];
    let failures = 0;

    function loginUsers(tierName, ids, count) {
        const selected = ids.slice(0, count);
        let logged = 0;
        for (const id of selected) {
            const username = `loaduser_${id}`;
            const loginRes = http.post(
                `${BASE_URL}/api/auth/login`,
                JSON.stringify({ username, password: TEST_PASSWORD }),
                { headers: { 'Content-Type': 'application/json' } }
            );

            if (loginRes.status === 200) {
                const body = JSON.parse(loginRes.body);
                userPool.push({
                    tier: tierName,
                    username,
                    memberId: body.result.id,
                    accessToken: body.result.accessToken,
                });
                logged++;
            } else {
                failures++;
                if (failures <= 5) {
                    console.log(`Login failed for ${username}: ${loginRes.status}`);
                }
            }
        }
        console.log(`  ${tierName}: ${logged}/${count} logged in`);
    }

    loginUsers('T1', manifest.tiers.T1.member_ids, T1_USERS);
    loginUsers('T2', manifest.tiers.T2.member_ids, T2_USERS);
    loginUsers('T3', manifest.tiers.T3.member_ids, T3_USERS);
    loginUsers('T4', manifest.tiers.T4.member_ids, T4_USERS);

    console.log(`Total: ${userPool.length} users logged in (${failures} failures)`);

    return {
        users: userPool,
        hotPostIds: manifest.hot_post_ids,
    };
}

// ─── Read Scenario (80% of traffic) ─────────────────────
export function readScenario(data) {
    const { users, hotPostIds } = data;
    if (!users || users.length === 0) return;

    const user = users[__VU % users.length];
    const headers = {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${user.accessToken}`,
    };

    const scenario = weightedRandom([
        { weight: 25, fn: () => scenarioFeedAll(headers) },
        { weight: 10, fn: () => scenarioFeedCore(headers) },
        { weight: 15, fn: () => scenarioPostDetail(headers) },
        { weight: 10, fn: () => scenarioProfile(headers, user) },
        { weight: 15, fn: () => scenarioNotifications(headers) },
        { weight: 10, fn: () => scenarioQuestions(headers) },
        { weight: 5, fn: () => scenarioSearch(headers) },
        { weight: 5, fn: () => scenarioComments(headers) },
        { weight: 5, fn: () => scenarioHotPost(headers, hotPostIds) },
    ]);

    scenario();

    // Log-normal think time: median ~1s, range 0.5-2.2s
    sleep(logNormalSleep(0, 0.5, 0.5, 2.2));
}

// ─── Write Scenario (20% of traffic) ────────────────────
export function writeScenario(data) {
    const { users } = data;
    if (!users || users.length === 0) return;

    const user = users[__VU % users.length];
    const headers = {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${user.accessToken}`,
    };

    const scenario = weightedRandom([
        { weight: 25, fn: () => scenarioCreatePost(headers) },
        { weight: 25, fn: () => scenarioCreateComment(headers) },
        { weight: 20, fn: () => scenarioLikeUnlike(headers) },
        { weight: 15, fn: () => scenarioFollowUnfollow(headers, user) },
        { weight: 15, fn: () => scenarioNotificationRead(headers) },
    ]);

    scenario();

    // Longer think time for write ops
    sleep(logNormalSleep(0.5, 0.8, 1.0, 4.5));
}

// ─── Read Scenarios ──────────────────────────────────────

function scenarioFeedAll(headers) {
    group('Feed ALL', () => {
        const res = http.get(`${BASE_URL}/api/posts?feedType=ALL&size=10`, {
            headers,
            tags: { name: 'GET /api/posts?feedType=ALL' },
        });
        requestCount.add(1);
        feedDuration.add(res.timings.duration);
        const ok = check(res, { 'feed ALL 200': (r) => r.status === 200 });
        errorRate.add(!ok);

        // Pagination
        if (res.status === 200) {
            try {
                const body = JSON.parse(res.body);
                if (body.result && body.result.hasNext && body.result.nextCursor) {
                    const p2 = http.get(
                        `${BASE_URL}/api/posts?feedType=ALL&size=10&cursor=${body.result.nextCursor}`,
                        { headers, tags: { name: 'GET /api/posts?feedType=ALL (page2)' } }
                    );
                    requestCount.add(1);
                    feedDuration.add(p2.timings.duration);
                    errorRate.add(p2.status !== 200);
                }
            } catch (_) {}
        }
    });
}

