function scenarioLikeUnlike(headers) {
    group('Like/Unlike', () => {
        const feedRes = http.get(`${BASE_URL}/api/posts?feedType=ALL&size=10`, {
            headers,
            tags: { name: 'GET /api/posts' },
        });
        requestCount.add(1);

        if (feedRes.status === 200) {
            try {
                const body = JSON.parse(feedRes.body);
                const posts = body.result && body.result.posts;
                if (posts && posts.length > 0) {
                    const post = posts[Math.floor(Math.random() * posts.length)];

                    const likeRes = http.post(
                        `${BASE_URL}/api/posts/${post.postId}/likes`,
                        null,
                        { headers, tags: { name: 'POST /api/posts/{postId}/likes' } }
                    );
                    requestCount.add(1);
                    likeDuration.add(likeRes.timings.duration);
                    errorRate.add(likeRes.status !== 200 && likeRes.status !== 409);

                    sleep(0.3);

                    // Unlike to maintain data consistency
                    const unlikeRes = http.del(
                        `${BASE_URL}/api/posts/${post.postId}/likes`,
                        null,
                        { headers, tags: { name: 'DELETE /api/posts/{postId}/likes' } }
                    );
                    requestCount.add(1);
                    likeDuration.add(unlikeRes.timings.duration);
                    errorRate.add(unlikeRes.status !== 200 && unlikeRes.status !== 404);
                }
            } catch (_) {}
        }
    });
}

function scenarioFollowUnfollow(headers, user) {
    group('Follow/Unfollow', () => {
        // Follow a random T1-T2 user
        const targetId = Math.floor(Math.random() * 510) + 1;
        if (targetId === user.memberId) return;

        const followRes = http.post(
            `${BASE_URL}/api/follows/${targetId}`,
            null,
            { headers, tags: { name: 'POST /api/follows/{memberId}' } }
        );
        requestCount.add(1);
        followDuration.add(followRes.timings.duration);
        // 409 = already following
        errorRate.add(followRes.status !== 200 && followRes.status !== 409);

        sleep(0.5);

        // Unfollow to maintain consistency
        const unfollowRes = http.del(
            `${BASE_URL}/api/follows/${targetId}`,
            null,
            { headers, tags: { name: 'DELETE /api/follows/{memberId}' } }
        );
        requestCount.add(1);
        followDuration.add(unfollowRes.timings.duration);
        errorRate.add(unfollowRes.status !== 200 && unfollowRes.status !== 404);
    });
}

function scenarioNotificationRead(headers) {
    group('NotificationRead', () => {
        // Get notification list and mark as read
        const listRes = http.get(`${BASE_URL}/api/notifications?size=5`, {
            headers,
            tags: { name: 'GET /api/notifications' },
        });
        requestCount.add(1);

        if (listRes.status === 200) {
            try {
                const body = JSON.parse(listRes.body);
                const notifications = body.result && body.result.notifications;
                if (notifications && notifications.length > 0) {
                    const noti = notifications[0];
                    if (noti.notificationId) {
                        const readRes = http.patch(
                            `${BASE_URL}/api/notifications/${noti.notificationId}/read`,
                            null,
                            { headers, tags: { name: 'PATCH /api/notifications/{id}/read' } }
                        );
                        requestCount.add(1);
                        errorRate.add(readRes.status !== 200 && readRes.status !== 204);
                    }
                }
            } catch (_) {}
        }
    });
}

